#include "dexmeguviz/dexmeguviz.h"
#include <windows.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"timing line %d: %s\n",__LINE__,#x);return 1;}}while(0)
static double elapsed(LARGE_INTEGER a,LARGE_INTEGER b,LARGE_INTEGER frequency){return 1000.0*(double)(b.QuadPart-a.QuadPart)/(double)frequency.QuadPart;}
int main(int argc,char **argv){FILE *f;long n;unsigned char *data;dmg_engine *engine=NULL;dmg_query *query=NULL;dmg_error error={0};LARGE_INTEGER freq;int k;const char *text="{\"schema_version\":1,\"relation\":{\"op\":\"join\",\"on\":\"target_ref\",\"left\":{\"op\":\"scan\",\"relation\":\"string_uses\"},\"right\":{\"op\":\"scan\",\"relation\":\"string_values\"}},\"max_results\":10000,\"max_work\":100000000}";
 CHECK(argc==2&&QueryPerformanceFrequency(&freq)&&(f=fopen(argv[1],"rb"))!=NULL);CHECK(!fseek(f,0,SEEK_END)&&(n=ftell(f))>0&&!fseek(f,0,SEEK_SET));data=malloc((size_t)n);CHECK(data&&fread(data,1,(size_t)n,f)==(size_t)n);fclose(f);CHECK(dmg_engine_create(NULL,&engine,&error)==DMG_OK);CHECK(dmg_query_compile_json(engine,(const uint8_t*)text,strlen(text),&query,&error)==DMG_OK);
 for(k=0;k<5;k++){dmg_source_spec sp={sizeof(sp),DMG_ABI_VERSION,DMG_INPUT_RAW_DEX,0,data,(uint64_t)n,"sample","raw",NULL};dmg_source_set_options so={sizeof(so),DMG_ABI_VERSION,"timing",1,8,4u<<20};dmg_reverse_join_options_v1 opt={sizeof(opt),DMG_ABI_VERSION,100000000,4u<<20,100000000,100000,10000,0,0};dmg_snapshot *snap=NULL;dmg_result *old=NULL,*cold=NULL,*warm=NULL;dmg_relation_info_v2 x={0},y={0},z={0};dmg_query_profile px={0},py={0},pz={0};dmg_reverse_profile_v1 cp={0},wp={0};LARGE_INTEGER t0,t1,t2,t3,tw;
 CHECK(dmg_snapshot_open_sources(engine,&sp,1,&so,&snap,&error)==DMG_OK);QueryPerformanceCounter(&t0);CHECK(dmg_query_execute(snap,query,&old,&error)==DMG_OK&&old);QueryPerformanceCounter(&t1);CHECK(dmg_query_execute_reverse_intersection_v2(snap,query,&opt,&cold,&error)==DMG_OK&&cold);QueryPerformanceCounter(&t2);CHECK(dmg_snapshot_reverse_profile_v1(snap,&cp,sizeof(cp))==DMG_OK&&cp.builds==1);QueryPerformanceCounter(&tw);CHECK(dmg_query_execute_reverse_intersection_v2(snap,query,&opt,&warm,&error)==DMG_OK&&warm);QueryPerformanceCounter(&t3);CHECK(dmg_snapshot_reverse_profile_v1(snap,&wp,sizeof(wp))==DMG_OK&&wp.reuses>cp.reuses);
 CHECK(dmg_result_get_relation_info_v2(old,&x,sizeof(x))==DMG_OK&&dmg_result_get_relation_info_v2(cold,&y,sizeof(y))==DMG_OK&&dmg_result_get_relation_info_v2(warm,&z,sizeof(z))==DMG_OK&&x.candidates_count==y.candidates_count&&x.candidates_count==z.candidates_count);CHECK(dmg_result_get_profile(old,&px)==DMG_OK&&dmg_result_get_profile(cold,&py)==DMG_OK&&dmg_result_get_profile(warm,&pz)==DMG_OK&&px.work_units==py.work_units&&px.work_units==pz.work_units);printf("%d scalar_ms=%.3f cold_ms=%.3f warm_ms=%.3f rows=%u logical_work=%llu builds=%llu reuses=%llu\n",k,elapsed(t0,t1,freq),elapsed(t1,t2,freq),elapsed(tw,t3,freq),x.candidates_count,(unsigned long long)px.work_units,(unsigned long long)cp.builds,(unsigned long long)wp.reuses);
 dmg_result_release(old);dmg_result_release(cold);dmg_result_release(warm);dmg_snapshot_release(snap);}
 dmg_query_release(query);dmg_engine_release(engine);free(data);return 0;}
